    "kpi_name": "Processing Efficiency Ratio",
    "kpi_alias": "PER, Processing Efficiency",
    "relevant_for_designations": null,
    "creation_mode": "sql_playground",
    "kpi_description": "Measures scan processing workflow efficiency by comparing data throughput to resource usage. Formula: PER = (GBSize × log10(TotalPts)) / (FlowHrs × (ProcCPU + ProcGPU) / 200). Higher values = more efficient. Processing Bottleneck = PER < 0.5. Grain: aggregate per (flowsoft, flowstage) after LEFT JOIN scanpointcloud on arcref only (intentional fanout). Filters: flowhrs > 0 AND (proccpu + procgpu) > 0. Verified on livesql_archeology: 1000 scanprocessing rows → 1245 rows after LEFT JOIN, all 20 (software, stage) combos are Efficient (avg_per range 12.4-39.1, all > 0.5).",
    "calculation_logic": null,
    "sql_query": "SELECT sp.flowsoft AS processing_software, sp.flowstage AS processing_stage, ROUND(AVG(sp.flowhrs), 1) AS avg_processing_hours, ROUND(AVG(sp.proccpu), 0) AS avg_cpu_usage_pct, ROUND(AVG(sp.procgpu), 0) AS avg_gpu_usage_pct, ROUND(AVG(s.gbsize), 1) AS avg_data_size_gb, ROUND(AVG(s.gbsize * LOG10(COALESCE(pc.totalpts, 1000000)) / (sp.flowhrs * (sp.proccpu + sp.procgpu) / 200)), 1) AS avg_per, CASE WHEN AVG(s.gbsize * LOG10(COALESCE(pc.totalpts, 1000000)) / (sp.flowhrs * (sp.proccpu + sp.procgpu) / 200)) < 0.5 THEN 'Bottleneck Detected' ELSE 'Efficient' END AS efficiency_status, COUNT(*) AS workflow_count FROM livesql_archeology_main_scanprocessing sp JOIN livesql_archeology_main_scans s ON sp.zoneref = s.zoneref LEFT JOIN livesql_archeology_main_scanpointcloud pc ON s.arcref = pc.arcref WHERE sp.flowhrs > 0 AND (sp.proccpu + sp.procgpu) > 0 GROUP BY sp.flowsoft, sp.flowstage ORDER BY CASE WHEN AVG(s.gbsize * LOG10(COALESCE(pc.totalpts, 1000000)) / (sp.flowhrs * (sp.proccpu + sp.procgpu) / 200)) < 0.5 THEN 1 ELSE 2 END, avg_per ASC AS agg_v2;",
